using System.Data;
using System.Text.Json;
using Dapper;
using Microsoft.Extensions.Logging;
using Sigov.Application.Frotas;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.Frotas;

public sealed class FrotasService(NpgsqlConnectionFactory factory,ILogger<FrotasService> logger):IFrotasService
{
 public async Task<FrotasDashboardDto> DashboardAsync(long t,long e,CancellationToken c)
 {
  const string sql="""select count(*) filter(where status='ATIVO') VeiculosAtivos,count(*) filter(where status='EM_MANUTENCAO') VeiculosEmManutencao from sigov.frotas_veiculo where tenant_id=@t and entidade_id=@e;select count(*) filter(where validade_cnh<current_date) CnhVencida,count(*) filter(where validade_cnh between current_date and current_date+30) CnhAVencer from sigov.frotas_motorista where tenant_id=@t and entidade_id=@e and status='ATIVO';select count(*) filter(where data_vencimento<current_date and status='VIGENTE') DocumentosVencidos,count(*) filter(where data_vencimento between current_date and current_date+30 and status='VIGENTE') DocumentosAVencer from sigov.frotas_documento where tenant_id=@t and entidade_id=@e;select count(*) AbastecimentosMes,coalesce(sum(valor_total),0) CustoAbastecimento from sigov.frotas_abastecimento where tenant_id=@t and entidade_id=@e and data_abastecimento>=date_trunc('month',current_date);select count(*) ManutencoesAbertas,coalesce(sum(coalesce(valor_final,valor_estimado)),0) CustoManutencao from sigov.frotas_manutencao where tenant_id=@t and entidade_id=@e and (status in('ABERTA','EM_EXECUCAO') or data_conclusao>=date_trunc('month',current_date));""";
  await using var cn=factory.CreateConnection();using var m=await cn.QueryMultipleAsync(Cmd(sql,new{t,e},c));dynamic v=await m.ReadSingleAsync();dynamic d=await m.ReadSingleAsync();dynamic doc=await m.ReadSingleAsync();dynamic a=await m.ReadSingleAsync();dynamic mt=await m.ReadSingleAsync();return new((long)v.veiculosativos,(long)v.veiculosemmanutencao,(long)d.cnhvencida,(long)d.cnhavencer,(long)doc.documentosvencidos,(long)doc.documentosavencer,(long)a.abastecimentosmes,(decimal)a.custoabastecimento+(decimal)mt.customanutencao,(long)mt.manutencoesabertas,(await UtilizacoesAsync(t,e,new(Tamanho:5),c)).Take(5).ToList(),(await OrdensAsync(t,e,new(Tamanho:5),c)).Take(5).ToList());
 }
 public Task<IReadOnlyList<VeiculoDto>> VeiculosAsync(long t,long e,FrotaFiltro f,CancellationToken c)=>List<VeiculoDto>("""select id,placa,marca,modelo,tipo,combustivel_principal CombustivelPrincipal,quilometragem_atual QuilometragemAtual,horimetro_atual HorimetroAtual,status,unidade_responsavel UnidadeResponsavel,bem_patrimonial_id BemPatrimonialId,renavam,chassi,ano_fabricacao AnoFabricacao,ano_modelo AnoModelo,observacoes from sigov.frotas_veiculo where tenant_id=@t and entidade_id=@e and (@status is null or status=@status) and (@busca is null or placa ilike '%'||@busca||'%' or modelo ilike '%'||@busca||'%') order by placa limit @lim""",t,e,f,c);
 public async Task<VeiculoDto?> VeiculoAsync(long t,long e,long id,CancellationToken c)=>(await List<VeiculoDto>("""select id,placa,marca,modelo,tipo,combustivel_principal CombustivelPrincipal,quilometragem_atual QuilometragemAtual,horimetro_atual HorimetroAtual,status,unidade_responsavel UnidadeResponsavel,bem_patrimonial_id BemPatrimonialId,renavam,chassi,ano_fabricacao AnoFabricacao,ano_modelo AnoModelo,observacoes from sigov.frotas_veiculo where tenant_id=@t and entidade_id=@e and id=@id""",new{t,e,id},c)).SingleOrDefault();
 public async Task<long> CriarVeiculoAsync(long t,long u,string corr,VeiculoInput i,CancellationToken c){ValidateVehicle(i);const string q="""insert into sigov.frotas_veiculo(tenant_id,entidade_id,placa,renavam,chassi,marca,modelo,ano_fabricacao,ano_modelo,tipo,combustivel_principal,quilometragem_atual,horimetro_atual,status,unidade_responsavel,bem_patrimonial_id,observacoes,created_by) values(@t,@EntidadeId,upper(trim(@Placa)),@Renavam,@Chassi,@Marca,@Modelo,@AnoFabricacao,@AnoModelo,@Tipo,@CombustivelPrincipal,@QuilometragemAtual,@HorimetroAtual,@Status,@UnidadeResponsavel,@BemPatrimonialId,@Observacoes,@u) returning id""";return await Insert(q,t,u,corr,i,"VEICULO",c);}
 public async Task EditarVeiculoAsync(long t,long u,string corr,long id,VeiculoInput i,CancellationToken c){ValidateVehicle(i);await using var cn=factory.CreateConnection();await cn.OpenAsync(c);await using var tx=await cn.BeginTransactionAsync(c);var before=await One(cn,tx,"select * from sigov.frotas_veiculo where id=@id and tenant_id=@t and entidade_id=@e for update",new{id,t,e=i.EntidadeId},c);if(before is null)throw new KeyNotFoundException("Veículo não encontrado.");if(i.QuilometragemAtual<(decimal)before.quilometragem_atual)throw new InvalidOperationException("Quilometragem regressiva não é permitida.");await cn.ExecuteAsync(Cmd("""update sigov.frotas_veiculo set placa=upper(trim(@Placa)),renavam=@Renavam,chassi=@Chassi,marca=@Marca,modelo=@Modelo,ano_fabricacao=@AnoFabricacao,ano_modelo=@AnoModelo,tipo=@Tipo,combustivel_principal=@CombustivelPrincipal,quilometragem_atual=@QuilometragemAtual,horimetro_atual=@HorimetroAtual,status=@Status,unidade_responsavel=@UnidadeResponsavel,bem_patrimonial_id=@BemPatrimonialId,observacoes=@Observacoes,updated_at=now(),updated_by=@u where id=@id""",Merge(i,new{u,id}),tx,c));await Audit(cn,tx,t,i.EntidadeId,"VEICULO",id,"EDITAR",before,i,u,corr,c);await tx.CommitAsync(c);}
 public Task<IReadOnlyList<MotoristaDto>> MotoristasAsync(long t,long e,FrotaFiltro f,CancellationToken c)=>List<MotoristaDto>("""select id,nome,case when length(cpf)=11 then left(cpf,3)||'.***.***-'||right(cpf,2) else '***' end CpfMascarado,cnh,categoria_cnh CategoriaCnh,validade_cnh ValidadeCnh,telefone,email,vinculo_lotacao VinculoLotacao,status,observacoes from sigov.frotas_motorista where tenant_id=@t and entidade_id=@e and (@status is null or status=@status) and (@busca is null or nome ilike '%'||@busca||'%') order by nome limit @lim""",t,e,f,c);
 public Task<long> CriarMotoristaAsync(long t,long u,string corr,MotoristaInput i,CancellationToken c){var cpf=Digits(i.Cpf);if(cpf.Length!=11||string.IsNullOrWhiteSpace(i.Nome)||string.IsNullOrWhiteSpace(i.Cnh))throw new ArgumentException("Nome, CPF válido e CNH são obrigatórios.");const string q="""insert into sigov.frotas_motorista(tenant_id,entidade_id,nome,cpf,cnh,categoria_cnh,validade_cnh,telefone,email,vinculo_lotacao,status,observacoes,created_by) values(@t,@EntidadeId,@Nome,@cpf,@Cnh,@CategoriaCnh,@ValidadeCnh,@Telefone,@Email,@VinculoLotacao,@Status,@Observacoes,@u) returning id""";return Insert(q,t,u,corr,Merge(i,new{cpf}),"MOTORISTA",c);}
 public Task<IReadOnlyList<UtilizacaoDto>> UtilizacoesAsync(long t,long e,FrotaFiltro f,CancellationToken c)=>List<UtilizacaoDto>("""select x.id,x.veiculo_id VeiculoId,v.placa,x.motorista_id MotoristaId,m.nome MotoristaNome,x.saida_em SaidaEm,x.retorno_em RetornoEm,x.km_saida KmSaida,x.km_retorno KmRetorno,x.destino,x.finalidade,x.status from sigov.frotas_utilizacao x join sigov.frotas_veiculo v on v.id=x.veiculo_id join sigov.frotas_motorista m on m.id=x.motorista_id where x.tenant_id=@t and x.entidade_id=@e and (@status is null or x.status=@status) order by x.saida_em desc limit @lim""",t,e,f,c);
 public async Task<long> CriarUtilizacaoAsync(long t,long u,string corr,UtilizacaoInput i,CancellationToken c){await using var cn=factory.CreateConnection();await cn.OpenAsync(c);await using var tx=await cn.BeginTransactionAsync(IsolationLevel.Serializable,c);var v=await One(cn,tx,"select * from sigov.frotas_veiculo where id=@id and tenant_id=@t and entidade_id=@e for update",new{id=i.VeiculoId,t,e=i.EntidadeId},c)??throw new KeyNotFoundException("Veículo não encontrado.");if((string)v.status!="ATIVO"||i.KmSaida<(decimal)v.quilometragem_atual)throw new InvalidOperationException("Veículo indisponível ou quilometragem regressiva.");var m=await One(cn,tx,"select * from sigov.frotas_motorista where id=@id and tenant_id=@t and entidade_id=@e",new{id=i.MotoristaId,t,e=i.EntidadeId},c)??throw new KeyNotFoundException("Motorista não encontrado.");if((string)m.status!="ATIVO"||((DateTime)m.validade_cnh).Date<DateTime.UtcNow.Date)throw new InvalidOperationException("Motorista suspenso, inativo ou com CNH vencida.");var id=await cn.ExecuteScalarAsync<long>(Cmd("""insert into sigov.frotas_utilizacao(tenant_id,entidade_id,veiculo_id,motorista_id,unidade_solicitante,saida_em,km_saida,destino,finalidade,observacao,created_by) values(@t,@EntidadeId,@VeiculoId,@MotoristaId,@UnidadeSolicitante,@SaidaEm,@KmSaida,@Destino,@Finalidade,@Observacao,@u) returning id""",Merge(i,new{t,u}),tx,c));await Audit(cn,tx,t,i.EntidadeId,"UTILIZACAO",id,"CRIAR",null,i,u,corr,c);await tx.CommitAsync(c);return id;}
 public async Task FinalizarUtilizacaoAsync(long t,long e,long u,string corr,long id,decimal km,DateTimeOffset retorno,CancellationToken c){await using var cn=factory.CreateConnection();await cn.OpenAsync(c);await using var tx=await cn.BeginTransactionAsync(c);var x=await One(cn,tx,"select * from sigov.frotas_utilizacao where id=@id and tenant_id=@t and entidade_id=@e for update",new{id,t,e},c)??throw new KeyNotFoundException();if((string)x.status!="ABERTO"||km<(decimal)x.km_saida)throw new InvalidOperationException("Utilização não está aberta ou km de retorno é inválida.");await cn.ExecuteAsync(Cmd("update sigov.frotas_utilizacao set status='FINALIZADO',km_retorno=@km,retorno_em=@retorno,updated_at=now(),updated_by=@u where id=@id;update sigov.frotas_veiculo set quilometragem_atual=greatest(quilometragem_atual,@km),updated_at=now(),updated_by=@u where id=@vid",new{id,km,retorno,u,vid=(long)x.veiculo_id},tx,c));await Audit(cn,tx,t,e,"UTILIZACAO",id,"FINALIZAR",x,new{km,retorno},u,corr,c);await tx.CommitAsync(c);}
 public Task<IReadOnlyList<AbastecimentoDto>> AbastecimentosAsync(long t,long e,FrotaFiltro f,CancellationToken c)=>List<AbastecimentoDto>("""select a.id,a.veiculo_id VeiculoId,v.placa,a.data_abastecimento DataAbastecimento,a.km_atual KmAtual,a.tipo_combustivel TipoCombustivel,a.litros,a.valor_unitario ValorUnitario,a.valor_total ValorTotal,a.documento_fiscal DocumentoFiscal from sigov.frotas_abastecimento a join sigov.frotas_veiculo v on v.id=a.veiculo_id where a.tenant_id=@t and a.entidade_id=@e order by a.data_abastecimento desc limit @lim""",t,e,f,c);
 public Task<long> CriarAbastecimentoAsync(long t,long u,string corr,AbastecimentoInput i,CancellationToken c)=>VehicleWrite(t,u,corr,i.EntidadeId,i.VeiculoId,i.KmAtual,"ABASTECIMENTO",i,async(cn,tx)=>await cn.ExecuteScalarAsync<long>(Cmd("""insert into sigov.frotas_abastecimento(tenant_id,entidade_id,veiculo_id,motorista_id,fornecedor_id,contrato_id,data_abastecimento,km_atual,tipo_combustivel,litros,valor_unitario,documento_fiscal,observacao,created_by) values(@t,@EntidadeId,@VeiculoId,@MotoristaId,@FornecedorId,@ContratoId,@DataAbastecimento,@KmAtual,@TipoCombustivel,@Litros,@ValorUnitario,@DocumentoFiscal,@Observacao,@u) returning id""",Merge(i,new{t,u}),tx,c)),c,i.Litros>0&&i.ValorUnitario>=0);
 public Task<IReadOnlyList<ManutencaoDto>> ManutencoesAsync(long t,long e,FrotaFiltro f,CancellationToken c)=>List<ManutencaoDto>("""select m.id,m.veiculo_id VeiculoId,v.placa,m.tipo,m.data_abertura DataAbertura,m.data_conclusao DataConclusao,m.km_abertura KmAbertura,m.descricao,m.valor_estimado ValorEstimado,m.valor_final ValorFinal,m.status,m.observacao from sigov.frotas_manutencao m join sigov.frotas_veiculo v on v.id=m.veiculo_id where m.tenant_id=@t and m.entidade_id=@e and (@status is null or m.status=@status) order by m.data_abertura desc limit @lim""",t,e,f,c);
 public async Task<long> CriarManutencaoAsync(long t,long u,string corr,ManutencaoInput i,CancellationToken c){var id=await VehicleWrite(t,u,corr,i.EntidadeId,i.VeiculoId,i.KmAbertura,"MANUTENCAO",i,async(cn,tx)=>{var x=await cn.ExecuteScalarAsync<long>(Cmd("""insert into sigov.frotas_manutencao(tenant_id,entidade_id,veiculo_id,tipo,data_abertura,km_abertura,fornecedor_id,contrato_id,descricao,valor_estimado,observacao,created_by) values(@t,@EntidadeId,@VeiculoId,@Tipo,@DataAbertura,@KmAbertura,@FornecedorId,@ContratoId,@Descricao,@ValorEstimado,@Observacao,@u) returning id""",Merge(i,new{t,u}),tx,c));await cn.ExecuteAsync(Cmd("update sigov.frotas_veiculo set status='EM_MANUTENCAO' where id=@id",new{id=i.VeiculoId},tx,c));return x;},c,i.ValorEstimado>=0);return id;}
 public async Task ConcluirManutencaoAsync(long t,long e,long u,string corr,long id,decimal valor,CancellationToken c){if(valor<0)throw new ArgumentException("Valor final inválido.");await using var cn=factory.CreateConnection();await cn.OpenAsync(c);await using var tx=await cn.BeginTransactionAsync(c);var x=await One(cn,tx,"select * from sigov.frotas_manutencao where id=@id and tenant_id=@t and entidade_id=@e for update",new{id,t,e},c)??throw new KeyNotFoundException();if((string)x.status is "CONCLUIDA" or "CANCELADA")throw new InvalidOperationException("Manutenção não pode ser concluída.");await cn.ExecuteAsync(Cmd("update sigov.frotas_manutencao set status='CONCLUIDA',valor_final=@valor,data_conclusao=now(),updated_by=@u,updated_at=now() where id=@id;insert into sigov.frotas_manutencao_historico(tenant_id,entidade_id,manutencao_id,status_anterior,status_novo,usuario_id,correlation_id) values(@t,@e,@id,@status,'CONCLUIDA',@u,@corr);update sigov.frotas_veiculo set status='ATIVO',updated_at=now(),updated_by=@u where id=@vid and not exists(select 1 from sigov.frotas_manutencao where veiculo_id=@vid and id<>@id and status in('ABERTA','EM_EXECUCAO'))",new{id,t,e,u,valor,corr,status=(string)x.status,vid=(long)x.veiculo_id},tx,c));await Audit(cn,tx,t,e,"MANUTENCAO",id,"CONCLUIR",x,new{valor},u,corr,c);await tx.CommitAsync(c);}
 public Task<IReadOnlyList<OrdemServicoDto>> OrdensAsync(long t,long e,FrotaFiltro f,CancellationToken c)=>List<OrdemServicoDto>("""select o.id,o.exercicio,o.numero,o.veiculo_id VeiculoId,v.placa,o.data_abertura DataAbertura,o.previsao_conclusao PrevisaoConclusao,o.descricao,o.status,coalesce(sum(i.quantidade*i.valor_unitario),0) ValorTotal,count(i.id)::int Itens from sigov.frotas_ordem_servico o join sigov.frotas_veiculo v on v.id=o.veiculo_id left join sigov.frotas_ordem_servico_item i on i.ordem_servico_id=o.id where o.tenant_id=@t and o.entidade_id=@e and (@status is null or o.status=@status) group by o.id,v.placa order by o.data_abertura desc limit @lim""",t,e,f,c);
 public async Task<OrdemServicoDto?> OrdemAsync(long t,long e,long id,CancellationToken c)=>(await List<OrdemServicoDto>("""select o.id,o.exercicio,o.numero,o.veiculo_id VeiculoId,v.placa,o.data_abertura DataAbertura,o.previsao_conclusao PrevisaoConclusao,o.descricao,o.status,coalesce(sum(i.quantidade*i.valor_unitario),0) ValorTotal,count(i.id)::int Itens from sigov.frotas_ordem_servico o join sigov.frotas_veiculo v on v.id=o.veiculo_id left join sigov.frotas_ordem_servico_item i on i.ordem_servico_id=o.id where o.tenant_id=@t and o.entidade_id=@e and o.id=@id group by o.id,v.placa""",new{t,e,id},c)).SingleOrDefault();
 public async Task<long> CriarOrdemAsync(long t,long u,string corr,OrdemServicoInput i,CancellationToken c){if(i.Itens.Count==0||i.Itens.Any(x=>x.Quantidade<=0||x.ValorUnitario<0||(x.Tipo!="SERVICO"&&x.MaterialId is null)))throw new ArgumentException("A OS exige itens válidos; peças e materiais exigem material vinculado.");await using var cn=factory.CreateConnection();await cn.OpenAsync(c);await using var tx=await cn.BeginTransactionAsync(c);var v=await One(cn,tx,"select * from sigov.frotas_veiculo where id=@id and tenant_id=@t and entidade_id=@e",new{id=i.VeiculoId,t,e=i.EntidadeId},c)??throw new KeyNotFoundException();if((string)v.status is "INATIVO" or "BAIXADO")throw new InvalidOperationException("Veículo indisponível para nova OS.");if(i.FornecedorId.HasValue&&!await cn.ExecuteScalarAsync<bool>(Cmd("select exists(select 1 from sigov.compras_fornecedor where id=@id and tenant_id=@t and entidade_id=@e and status='ATIVO')",new{id=i.FornecedorId,t,e=i.EntidadeId},tx,c)))throw new InvalidOperationException("Fornecedor inexistente, suspenso ou inativo.");var id=await cn.ExecuteScalarAsync<long>(Cmd("""insert into sigov.frotas_ordem_servico(tenant_id,entidade_id,exercicio,numero,veiculo_id,manutencao_id,fornecedor_id,data_abertura,previsao_conclusao,descricao,created_by) values(@t,@EntidadeId,@Exercicio,@Numero,@VeiculoId,@ManutencaoId,@FornecedorId,@DataAbertura,@PrevisaoConclusao,@Descricao,@u) returning id""",Merge(i,new{t,u}),tx,c));foreach(var x in i.Itens)await cn.ExecuteAsync(Cmd("""insert into sigov.frotas_ordem_servico_item(tenant_id,entidade_id,ordem_servico_id,descricao,tipo,quantidade,valor_unitario,material_id,almoxarifado_id,contrato_id) values(@t,@e,@id,@Descricao,@Tipo,@Quantidade,@ValorUnitario,@MaterialId,@AlmoxarifadoId,@ContratoId)""",Merge(x,new{t,e=i.EntidadeId,id}),tx,c));await Audit(cn,tx,t,i.EntidadeId,"ORDEM_SERVICO",id,"CRIAR",null,i,u,corr,c);await tx.CommitAsync(c);return id;}
 public async Task AlterarOrdemAsync(long t,long e,long u,string corr,long id,string acao,CancellationToken c){var novo=acao switch{"aprovar"=>"APROVADA","cancelar"=>"CANCELADA","concluir"=>"CONCLUIDA",_=>throw new ArgumentException("Ação inválida.")};await using var cn=factory.CreateConnection();await cn.OpenAsync(c);await using var tx=await cn.BeginTransactionAsync(IsolationLevel.Serializable,c);var os=await One(cn,tx,"select * from sigov.frotas_ordem_servico where id=@id and tenant_id=@t and entidade_id=@e for update",new{id,t,e},c)??throw new KeyNotFoundException();if((string)os.status=="CANCELADA"||(novo=="CONCLUIDA"&&(string)os.status is not ("APROVADA" or "EM_EXECUCAO")))throw new InvalidOperationException("Transição de OS inválida.");if(novo=="CONCLUIDA"){var items=(await cn.QueryAsync<dynamic>(Cmd("select * from sigov.frotas_ordem_servico_item where ordem_servico_id=@id for update",new{id},tx,c))).AsList();if(items.Count==0)throw new InvalidOperationException("OS sem itens não pode ser concluída.");foreach(var x in items.Where(x=>(string)x.tipo!="SERVICO")){if(x.material_id is null||x.almoxarifado_id is null)throw new InvalidOperationException("Peça/material sem origem de estoque definida.");var estoque=await One(cn,tx,"select * from sigov.almoxarifado_estoque where tenant_id=@t and entidade_id=@e and material_id=@m and almoxarifado_id=@a for update",new{t,e,m=(long)x.material_id,a=(long)x.almoxarifado_id},c);if(estoque is null||(decimal)estoque.quantidade<(decimal)x.quantidade)throw new InvalidOperationException("Estoque insuficiente; conclusão bloqueada.");var antes=(decimal)estoque.quantidade;var depois=antes-(decimal)x.quantidade;await cn.ExecuteAsync(Cmd("update sigov.almoxarifado_estoque set quantidade=@depois,updated_at=now() where id=@eid;insert into sigov.almoxarifado_movimentacao(tenant_id,entidade_id,almoxarifado_id,material_id,tipo,motivo,quantidade,valor_unitario,documento_origem,saldo_antes,saldo_depois,usuario_id,correlation_id) values(@t,@e,@a,@m,'SAIDA','CONSUMO',@q,@vu,@doc,@antes,@depois,@u,@corr) returning id",new{t,e,a=(long)x.almoxarifado_id,m=(long)x.material_id,q=(decimal)x.quantidade,vu=(decimal)x.valor_unitario,doc=$"FROTAS-OS-{os.numero}",antes,depois,u,corr,eid=(long)estoque.id},tx,c));var mov=await cn.ExecuteScalarAsync<long>(Cmd("select currval(pg_get_serial_sequence('sigov.almoxarifado_movimentacao','id'))",null,tx,c));await cn.ExecuteAsync(Cmd("update sigov.frotas_ordem_servico_item set movimentacao_almoxarifado_id=@mov where id=@iid",new{mov,iid=(long)x.id},tx,c));}}
  }await cn.ExecuteAsync(Cmd("update sigov.frotas_ordem_servico set status=@novo,updated_at=now(),updated_by=@u where id=@id;insert into sigov.frotas_ordem_servico_historico(tenant_id,entidade_id,ordem_servico_id,status_anterior,status_novo,usuario_id,correlation_id) values(@t,@e,@id,@anterior,@novo,@u,@corr)",new{id,t,e,u,corr,novo,anterior=(string)os.status},tx,c));await Audit(cn,tx,t,e,"ORDEM_SERVICO",id,novo,os,new{novo},u,corr,c);await tx.CommitAsync(c);}
 public Task<IReadOnlyList<DocumentoDto>> DocumentosAsync(long t,long e,FrotaFiltro f,CancellationToken c)=>List<DocumentoDto>("""select d.id,d.veiculo_id VeiculoId,v.placa,d.tipo,d.numero,d.data_emissao DataEmissao,d.data_vencimento DataVencimento,case when d.status='VIGENTE' and d.data_vencimento<current_date then 'VENCIDO' else d.status end status,d.observacao from sigov.frotas_documento d join sigov.frotas_veiculo v on v.id=d.veiculo_id where d.tenant_id=@t and d.entidade_id=@e order by d.data_vencimento limit @lim""",t,e,f,c);
 public Task<long> CriarDocumentoAsync(long t,long u,string corr,DocumentoInput i,CancellationToken c){if(i.DataEmissao>i.DataVencimento)throw new ArgumentException("Vencimento anterior à emissão.");const string q="""insert into sigov.frotas_documento(tenant_id,entidade_id,veiculo_id,tipo,numero,data_emissao,data_vencimento,observacao,created_by) values(@t,@EntidadeId,@VeiculoId,@Tipo,@Numero,@DataEmissao,@DataVencimento,@Observacao,@u) returning id""";return Insert(q,t,u,corr,i,"DOCUMENTO",c);}

 async Task<long> VehicleWrite<T>(long t,long u,string corr,long e,long vid,decimal km,string entity,T input,Func<System.Data.Common.DbConnection,IDbTransaction,Task<long>> write,CancellationToken c,bool valid=true){if(!valid)throw new ArgumentException("Valores informados são inválidos.");await using var cn=factory.CreateConnection();await cn.OpenAsync(c);await using var tx=await cn.BeginTransactionAsync(c);var v=await One(cn,tx,"select * from sigov.frotas_veiculo where id=@vid and tenant_id=@t and entidade_id=@e for update",new{vid,t,e},c)??throw new KeyNotFoundException("Veículo não encontrado.");if(((string)v.status is "INATIVO" or "BAIXADO") || km<(decimal)v.quilometragem_atual)throw new InvalidOperationException("Veículo indisponível ou quilometragem regressiva.");var id=await write(cn,tx);await cn.ExecuteAsync(Cmd("update sigov.frotas_veiculo set quilometragem_atual=greatest(quilometragem_atual,@km),updated_at=now(),updated_by=@u where id=@vid",new{km,u,vid},tx,c));await Audit(cn,tx,t,e,entity,id,"CRIAR",null,input,u,corr,c);await tx.CommitAsync(c);return id;}
 async Task<long> Insert<T>(string sql,long t,long u,string corr,T input,string entity,CancellationToken c){try{await using var cn=factory.CreateConnection();await cn.OpenAsync(c);await using var tx=await cn.BeginTransactionAsync(c);var id=await cn.ExecuteScalarAsync<long>(Cmd(sql,Merge(input,new{t,u}),tx,c));var e=(long)(input!.GetType().GetProperty("EntidadeId")!.GetValue(input)!);await Audit(cn,tx,t,e,entity,id,"CRIAR",null,input,u,corr,c);await tx.CommitAsync(c);return id;}catch(Exception ex){logger.LogError(ex,"Falha crítica ao persistir {Entidade}",entity);throw;}}
 Task<IReadOnlyList<T>> List<T>(string sql,long t,long e,FrotaFiltro f,CancellationToken c)=>List<T>(sql,new{t,e,status=f.Status,busca=f.Busca,lim=Math.Clamp(f.Tamanho,1,500)},c);async Task<IReadOnlyList<T>> List<T>(string sql,object p,CancellationToken c){await using var cn=factory.CreateConnection();return (await cn.QueryAsync<T>(Cmd(sql,p,c))).AsList();}
 static async Task<dynamic?> One(System.Data.Common.DbConnection cn,IDbTransaction tx,string sql,object p,CancellationToken c)=>await cn.QuerySingleOrDefaultAsync(Cmd(sql,p,tx,c));
 static Task<int> Audit(System.Data.Common.DbConnection cn,IDbTransaction tx,long t,long e,string entity,long id,string op,object? before,object? after,long u,string corr,CancellationToken c)=>cn.ExecuteAsync(Cmd("insert into sigov.frotas_auditoria(tenant_id,entidade_id,entidade,registro_id,operacao,antes,depois,usuario_id,correlation_id) values(@t,@e,@entity,@id,@op,cast(@before as jsonb),cast(@after as jsonb),@u,@corr)",new{t,e,entity,id,op,before=before is null?null:JsonSerializer.Serialize(before),after=after is null?null:JsonSerializer.Serialize(after),u,corr},tx,c));
 static CommandDefinition Cmd(string sql,object? p,CancellationToken c)=>new(sql,p,cancellationToken:c);static CommandDefinition Cmd(string sql,object? p,IDbTransaction tx,CancellationToken c)=>new(sql,p,tx,cancellationToken:c);
 static object Merge(object a,object b){var d=new Dictionary<string,object?>();foreach(var x in a.GetType().GetProperties())d[x.Name]=x.GetValue(a);foreach(var x in b.GetType().GetProperties())d[x.Name]=x.GetValue(b);return d;}static string Digits(string s)=>new(s.Where(char.IsDigit).ToArray());static void ValidateVehicle(VeiculoInput i){if(string.IsNullOrWhiteSpace(i.Placa)||string.IsNullOrWhiteSpace(i.Marca)||string.IsNullOrWhiteSpace(i.Modelo)||i.QuilometragemAtual<0)throw new ArgumentException("Placa, marca, modelo e quilometragem válida são obrigatórios.");}
